def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [[0] * w for _ in range(h)]
    # Extend each visible parallel stripe across its full diagonal.
    for r in range(h):
        for c in range(w):
            d = c - r
            if d == -2:
                out[r][c] = 4
            elif d in (-8, -9):
                out[r][c] = 3
            elif d == 9:
                out[r][c] = 5
    return out

